INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0.2, "travel_topdrama_r_2000_talk_smile_loop", "travel_topdrama_r_2000_talk_smile_in", 0, 3, 20012, "", 105811, "", 1200120013);
