INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, "vo_travel_talk_20002_02", 0, 21, 20022, "", "vo_travel_talk", "", 1200220012);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "どういたしまして♪\nケガはないのが一番だけど、\n困ったときは遠慮なく相談してね？", 10, 11, 20022, 0, 100211, 0, 1200220013);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20022, "", 0, "", 1200220014);
