INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0.2, "travel_topdrama_r_2000_talk_arm_crossed_loop", "travel_topdrama_r_2000_talk_arm_crossed_in", 0, 3, 20052, "", 105611, "", 1200520008);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, "vo_travel_talk_20005_01", 0, 21, 20052, "", "vo_travel_talk", "", 1200520009);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "そうかい。\nじゃあまずは、焚火の枝を集める運命を\n受け入れてもらえるかい？", 10, 11, 20052, 0, 105611, 0, 1200520010);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20052, "", 0, "", 1200520011);
