INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0.2, "travel_topdrama_r_2000_talk_doya_loop", "travel_topdrama_r_2000_talk_doya_in_blink", 0, 3, 20052, "", 100911, "", 1200520013);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, "vo_travel_talk_20005_02", 0, 21, 20052, "", "vo_travel_talk", "", 1200520014);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "ふっ、既にその運命は受け入れている！\n……のだが、その、全然集まらなくて。\nよければ手伝ってほしいんだが。", 10, 11, 20052, 0, 100911, 0, 1200520015);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20052, "", 0, "", 1200520016);
