INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "えっと、こんな感じですか？\n……わわっ、バランスが！？\nなかなか難しいですね……", 10, 11, 20072, 0, 105411, 0, 1200720010);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20072, "", 0, "", 1200720011);
