INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "なに言ってるべさ～！\nリンリンこそしっかり歩いて、\n体を鍛え直さねぇと！", 10, 11, 20102, 0, 103311, 0, 1201020010);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20102, "", 0, "", 1201020011);
