INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "おおきに～♪\nこれを食べて、うちもカオリはん\nみたいに元気に冒険せなな～♪", 10, 11, 20122, 0, 101011, 0, 1201220017);
