INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "ねねね！\nみんなで記念撮影しよ？\nあとで見返したら絶対エモいっしょ！", 10, 11, 20162, 0, 101611, 0, 1201620005);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20162, "", 0, "", 1201620006);
