INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0.2, "travel_topdrama_r_2000_talk_arm_crossed_loop_sad", "travel_topdrama_r_2000_talk_arm_crossed_in_sad", 0, 3, 20172, "", 106611, "", 1201720008);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, "vo_travel_talk_20017_01", 0, 21, 20172, "", "vo_travel_talk", "", 1201720009);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "あ、相変わらずのケンカバカですね……\nあたしはこんな面倒な仕事放り出して、\nさっさとランドソルに帰りてーですよ。", 10, 11, 20172, 0, 106611, 0, 1201720010);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20172, "", 0, "", 1201720011);
