INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0.2, "travel_topdrama_r_2000_talk_doya_loop_surprise", "travel_topdrama_r_2000_talk_doya_in_surprise", 0, 3, 20172, "", 106511, "", 1201720013);
