INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0.2, "travel_topdrama_r_2000_talk_doya_loop_sad", "travel_topdrama_r_2000_talk_doya_in_sad", 0, 3, 20192, "", 107011, "", 1201920008);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", 0, "vo_travel_talk_20019_01", 0, 21, 20192, "", "vo_travel_talk", "", 1201920009);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "はぁ……謹んでお断りします。\nそれと悪事というのは露見しないよう、\nこっそりと行うものですよ？", 10, 11, 20192, 0, 107011, 0, 1201920010);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20192, "", 0, "", 1201920011);
