INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "今日の冒険、いつかお芝居にして\nみんなに見せてあげたいなぁ……♪\nアヤネとクルミの大冒険、なんてどう？", 10, 11, 20222, 0, 102111, 0, 1202220006);
INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES ("", "", "", "", "", 91, 20222, "", 0, "", 1202220007);
