INSERT INTO `v1_1bd2c1611552d9709ec1fce557b027de5d7aaf84e23f116a1d9ae79287254ba8` VALUES (1, 0, 1, "今度はあいつと一緒に……\nどこに行こうかしら。\nエスコートしてもらわなくちゃね。", 10, 11, 20272, 0, 123011, 0, 1202720008);
